p=Path('$TMPDIR/entry-layer-eval-3skx597l/w-long.core-3/sandbox/home/Downloads/关西攻略截图')
print('directory_exists',p.exists())
if p.exists():
 for f in p.iterdir():
  if f.is_file():
   print(str(f), 'bytes', f.stat().st_size)
   if f.suffix.lower()=='.png':
    import struct
    b=f.read_bytes()
    print('signature', b[:8], 'dimensions',struct.unpack('>II',b[16:24]) if len(b)>=24 else None)

