from pathlib import Path
from PIL import Image
base=Path('$TMPDIR/entry-layer-eval-z6lpasdf/w-third-back.core-1/sandbox/home/Downloads/手机对比')
for name in ['星澜_S9_规格.png','青梧_P70_规格.png','远岫_M5_规格.png']:
 p=base/name
 print(str(p),'exists=',p.exists())
 if p.exists():
  print('bytes=',p.stat().st_size)
  try:
   with Image.open(p) as im:
    print('format=',im.format,'size=',im.size,'metadata=',im.info)
    im.verify()
  except Exception as e: print(type(e).__name__,str(e))

